14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let mut final_len = args.len();
25	    let mut raw_args = clap_lex::RawArgs::new(args);
26	
27	    // A multicall binary chooses its applet from the file name it was invoked
28	    // as, just like the parser reinterprets `argv[0]` as the first word. The
29	    // resolved applet is inserted right after `argv[0]` so the regular loop
30	    // descends into it; from then on completion is scoped to that applet and
31	    // never sees the aggregate command's root.
32	    //
33	    // `arg_index` addresses the words the caller passed, where `argv[0]` is
34	    // index 0. The inserted word sits at index 1, so a cursor on any later word
35	    // moves one position to the right.
36	    let mut arg_index = arg_index;
37	    // Whether the resolved applet was inserted right after `argv[0]`.
38	    let mut descended_applet = false;
39	    if cmd.is_multicall_set() {
40	        let mut argv0_cursor = raw_args.cursor();
41	        if let Some(argv0) = raw_args.next_os(&mut argv0_cursor) {
42	            if let Some(applet) = std::path::Path::new(argv0)
43	                .file_stem()
44	                .and_then(|file_stem| file_stem.to_str())
45	            {
46	                // Borrow `cmd` through an owned name so `raw_args` can be mutated.
47	                let applet = applet.to_owned();
48	                if cmd.find_subcommand(&applet).is_none() {
49	                    return Err(std::io::Error::other(format!(
50	                        "unrecognized multicall command `{applet}`"
51	                    )));
52	                }
53	                raw_args.insert(&argv0_cursor, [OsString::from(applet)]);
54	                descended_applet = true;
55	                final_len += 1;
56	                if arg_index != 0 {
57	                    arg_index += 1;
58	                }
59	            }
60	        }
61	    }
62	
63	    // A cursor at or past the final word names nothing to complete. (Shells
64	    // that complete a freshly typed empty word append it to `args` and address
65	    // its index instead, so it is still completed normally.)
66	    if arg_index >= final_len {
67	        return Ok(Vec::new());
68	    }
69	    // In multicall mode `argv[0]` was consumed to select the applet and is no
70	    // longer a logical word, so a cursor on it completes nothing rather than
71	    // erroring or completing at the aggregate root. This keeps no-binary-name
72	    // cursor semantics: logical words begin after the resolved applet.
73	    if descended_applet && arg_index == 0 {
74	        return Ok(Vec::new());
75	    }
76	
77	    let mut cursor = raw_args.cursor();
78	    let mut target_cursor = raw_args.cursor();
79	    raw_args.seek(
80	        &mut target_cursor,
81	        clap_lex::SeekFrom::Start(arg_index as u64),
82	    );
83	    // As we loop, `cursor` will always be pointing to the next item
84	    raw_args.next_os(&mut target_cursor);
85	    debug!("complete: target_cursor={target_cursor:?}");
86	
87	    // Multicall already consumed `argv[0]` to select the applet and inserted
88	    // that applet in its place, so it is never parsed as a word again, even in
89	    // no-binary-name mode. Without multicall, `argv[0]` is skipped as the
90	    // binary name unless `no_binary_name` is set.
91	    if descended_applet || !cmd.is_no_binary_name_set() {
92	        raw_args.next_os(&mut cursor);
93	    }
94	
95	    let mut current_cmd = &*cmd;
96	    let mut pos_index = 1;
97	    let mut is_escaped = false;
98	    let mut next_state = ParseState::ValueDone;
99	    let mut used_args = Vec::<clap::Id>::new();
100	    // Once a committed word selected an external subcommand, every remaining
101	    // word belongs to that external program and is never completed here.
102	    let mut in_external = false;
103	    while let Some(arg) = raw_args.next(&mut cursor) {
104	        let current_state = next_state;
105	        next_state = ParseState::ValueDone;
106	        debug!(
107	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
108	            arg.to_value_os(),
109	        );
110	        if let ParseState::Opt(state) = &current_state {
111	            // A value terminator ends a multi-value option regardless of the
112	            // word's shape: unlike a flag-like word, it never starts a new
113	            // argument, and unlike any other word, it is never one of the
114	            // option's values. A flag-shaped terminator only wins over flag
115	            // parsing when the option accepts hyphen values, matching the
116	            // parser's precedence.
117	            let opt = state.opt;
118	            if is_value_terminator(opt, &arg)
119	                && (opt.is_allow_hyphen_values_set() || !is_flag_like(&arg))
120	            {
121	                if cursor == target_cursor {
122	                    // The cursor sits on the terminator itself. Complete as if
123	                    // it had already been submitted and an empty word followed,
124	                    // so ordinary completion resumes and the terminator is not
125	                    // offered as a candidate.
126	                    raw_args.insert(&target_cursor, [OsString::new()]);
127	                    let mut word_cursor = target_cursor;
128	                    let word = raw_args
129	                        .next(&mut word_cursor)
130	                        .expect("an empty word was just inserted");
131	                    return complete_arg(
132	                        &word,
133	                        current_cmd,
134	                        current_dir,
135	                        pos_index,
136	                        is_escaped,
137	                        ParseState::ValueDone,
138	                        &used_args,
139	                    );
140	                }
141	                next_state = ParseState::ValueDone;
142	                continue;
143	            }
144	        }
145	        if in_external {
146	            // A committed word already selected an external subcommand; this
147	            // word (and every later one) is an argument of that external
148	            // program. Its command line is unknown, so rather than falling
149	            // back to the current command's subcommands, options, or
150	            // positionals, completion succeeds with an empty set.
151	            if cursor == target_cursor {
152	                return Ok(Vec::new());
153	            }
154	            continue;
155	        }
156	
157	        if cursor == target_cursor {
158	            return complete_arg(
159	                &arg,
160	                current_cmd,
161	                current_dir,
162	                pos_index,
163	                is_escaped,
164	                current_state,
165	                &used_args,
166	            );
167	        }
168	
169	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
170	            if let Ok(value) = arg.to_value() {
171	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
172	                    current_cmd = next_cmd;
173	                    pos_index = 1;
174	                    used_args.clear();
175	                    continue;
176	                }
177	                // An unknown plain word, with no positional slot left to
178	                // fill, selects an external subcommand: the parser routes
179	                // everything after it to that external program. Flag-like
180	                // words and the escape are still parsed as flags, matching
181	                // that precedence, and an empty word is a cursor placeholder
182	                // rather than a program name.
183	                if current_cmd.is_allow_external_subcommands_set()
184	                    && !arg.is_empty()
185	                    && !arg.is_escape()
186	                    && arg.to_long().is_none()
187	                    && arg.to_short().is_none()
188	                    && find_positional(current_cmd, pos_index, false).is_none()
189	                {
190	                    in_external = true;
191	                    continue;
192	                }
193	            }
194	        }
195	
196	        // A strict delimited group whose previous word opened another fragment
197	        // (a trailing delimiter) or went invalid owns the next word outright: a
198	        // flag, the `--` escape, or a subcommand name is then another value of
199	        // the group, never a scope switch. A continuation word that fills the
200	        // group closes it; otherwise the group stays pending for its remaining
201	        // fragments.
202	        if let ParseState::Opt(state) = &current_state {
203	            if state.is_strict_group() && (state.open || state.invalid) {
204	                let mut state = state.clone();
205	                state.observe(arg.to_value_os(), false);
206	                next_state =
207	                    if !state.invalid && !state.open && state.used.len() == state.capacity() {
208	                        ParseState::ValueDone
209	                    } else {
210	                        ParseState::Opt(state)
211	                    };
212	                continue;
213	            }
214	        }
215	
216	        if is_escaped {
217	            (next_state, pos_index) =
218	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
219	        } else if arg.is_escape() {
220	            is_escaped = true;
221	            // Like the parser, `--` jumps straight to a `last(true)`
222	            // positional, skipping any unfilled positionals.
223	            if let Some(last_index) = current_cmd
224	                .get_positionals()
225	                .filter(|p| p.is_last_set())
226	                .filter_map(|p| p.get_index())
227	                .max()
228	            {
229	                pos_index = last_index;
230	            }
231	        } else if opt_allows_hyphen(&current_state, &arg) {
232	            match current_state {
233	                ParseState::Opt(mut state) => {
234	                    state.observe(arg.to_value_os(), false);
235	                    next_state = state.finish();
236	                }
237	                _ => unreachable!("else branch is only reachable in Opt state"),
238	            }
239	        } else if let Some((flag, value)) = arg.to_long() {
240	            if let Ok(flag) = flag {
241	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
242	
243	                if let Some(opt) = opt {
244	                    record_used_arg(&mut used_args, opt.get_id());
245	                    if opt.get_num_args().expect("built").takes_values() {
246	                        // An attached value (`--opt=value`) counts toward the
247	                        // option's values just like a space-separated one, so
248	                        // that completing after `--opt=value` sees the same
249	                        // state as completing after `--opt value`.
250	                        // An empty attached value (`--opt=`) types no value
251	                        // yet, so the option stays pending.
252	                        let mut state = OptState::new(opt);
253	                        if let Some(value) = value.filter(|v| !v.is_empty()) {
254	                            state.observe(value, true);
255	                        }
256	                        next_state = state.finish();
257	                    };
258	                } else if pos_allows_hyphen(current_cmd, pos_index) {
259	                    (next_state, pos_index) =
260	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
261	                }
262	            }
263	        } else if let Some(short) = arg.to_short() {
264	            let (_, matched_opts, takes_value_opt, mut short) =
265	                parse_shortflags(current_cmd, short);
266	            for opt in &matched_opts {
267	                record_used_arg(&mut used_args, opt.get_id());
268	            }
269	            if let Some(opt) = takes_value_opt {
270	                // An attached value (`-ovalue`, `-o=value`) counts toward the
271	                // option's values just like a space-separated one. An empty
272	                // attached value (`-o=`) types no value yet, so the option
273	                // stays pending instead of being treated as satisfied.
274	                let mut state = OptState::new(opt);
275	                if let Some(value) = short
276	                    .next_value_os()
277	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
278	                    .filter(|v| !v.is_empty())
279	                {
280	                    state.observe(value, true);
281	                }
282	                next_state = state.finish();
283	            } else if pos_allows_hyphen(current_cmd, pos_index) {
284	                (next_state, pos_index) =
285	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
286	            }
287	        } else {
288	            match current_state {
289	                ParseState::ValueDone | ParseState::Pos(..) => {
290	                    (next_state, pos_index) =
291	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
292	                }
293	                ParseState::Opt(mut state) => {
294	                    state.observe(arg.to_value_os(), false);
295	                    next_state = state.finish();
296	                }
297	            }
298	        }
299	    }
300	
301	    Err(std::io::Error::other("no completion generated"))
302	}
303	
304	#[derive(Debug, PartialEq, Eq, Clone)]
305	enum ParseState<'a> {
306	    /// Parsing a value done, there is no state to record.
307	    ValueDone,
308	
309	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
310	    Pos((usize, usize)),
311	
312	    /// Parsing a optional flag argument
313	    Opt(OptState<'a>),
314	}
315	
316	/// State kept while the values of an option are still being parsed.
317	#[derive(Debug, PartialEq, Eq, Clone)]
318	struct OptState<'a> {
319	    opt: &'a clap::Arg,
320	    /// Shell-word values consumed, counted the way the parser does so that
321	    /// [`ArgValueCompleter::complete_at`] keeps indexing shell arguments
322	    /// rather than delimiter-separated fragments.
323	    words: usize,
324	    /// Canonical possible-value names of the valid, committed fragments of
325	    /// the current occurrence. Only populated for strict delimited groups.
326	    used: Vec<String>,
327	    /// Whether the most recent shell word ended with the value delimiter, so
328	    /// the word under the cursor is still filling this group (and may not
329	    /// switch scope no matter how it is shaped).
330	    open: bool,
331	    /// Whether a committed fragment of the current group was invalid (empty,
332	    /// unknown, duplicated, or past the group's capacity). Such a group stays
333	    /// locked on value completion and never yields candidates or lets a later
334	    /// word switch scope.
335	    invalid: bool,
336	}
337	
338	impl<'a> OptState<'a> {
339	    fn new(opt: &'a clap::Arg) -> Self {
340	        Self {
341	            opt,
342	            words: 0,
343	            used: Vec::new(),
344	            open: false,
345	            invalid: false,
346	        }
347	    }
348	
349	    fn is_strict_group(&self) -> bool {
350	        is_strict_group_arg(self.opt)
351	    }
352	
353	    /// Maximum number of values the option accepts; for strict delimited
354	    /// groups this is the number of fragments allowed in one occurrence.
355	    fn capacity(&self) -> usize {
356	        self.opt.get_num_args().expect("built").max_values()
357	    }
358	
359	    /// Record a shell word as a value of this option.
360	    ///
361	    /// `attached` marks a value glued to its flag (`--opt=a,b`). For options
362	    /// whose delimiter is not a strict group, such a word counts every
363	    /// delimiter-separated fragment toward the value range; a space-separated
364	    /// word counts once. For strict groups the fragments are instead validated
365	    /// into `used`, except the empty slot still being typed after a trailing
366	    /// delimiter.
367	    fn observe(&mut self, word: &OsStr, attached: bool) {
368	        if !self.is_strict_group() {
369	            let count = if attached {
370	                attached_value_count(self.opt, word)
371	            } else {
372	                1
373	            };
374	            self.words += count;
375	            return;
376	        }
377	
378	        self.words += 1;
379	        if self.invalid {
380	            return;
381	        }
382	        let delimiter = self.opt.get_value_delimiter().expect("strict group");
383	        let capacity = self.capacity();
384	        self.open = word.to_string_lossy().ends_with(delimiter);
385	        let Some(word) = word.to_str() else {
386	            self.invalid = true;
387	            return;
388	        };
389	        let mut fragments = word.split(delimiter);
390	        if self.open {
391	            // A trailing delimiter opens the slot still being typed, so its
392	            // empty fragment is not a committed value.
393	            fragments.next_back();
394	        }
395	        for fragment in fragments {
396	            if self.used.len() >= capacity {
397	                self.invalid = true;
398	                break;
399	            }
400	            match canonical_possible_value(self.opt, fragment) {
401	                Some(name) if !self.used.contains(&name) => self.used.push(name),
402	                _ => {
403	                    // Empty (also a doubled delimiter), unknown, or duplicated
404	                    // fragment: the parser would reject this group.
405	                    self.invalid = true;
406	                    break;
407	                }
408	            }
409	        }
410	    }
411	
412	    /// Consume a value and return the state parsing should resume with.
413	    ///
414	    /// The delimiter separates several fragments within one shell word, so a
415	    /// word that does not end with the delimiter is a complete value group and
416	    /// ordinary parsing resumes on the next word. A trailing delimiter instead
417	    /// opens a fragment still being typed, and an invalid committed fragment
418	    /// cannot be salvaged; both keep the group locked on values. An empty
419	    /// attached value (`--opt=`) leaves the option waiting for its first value.
420	    fn finish(self) -> ParseState<'a> {
421	        if self.is_strict_group() {
422	            if self.words == 0 || self.invalid || self.open {
423	                ParseState::Opt(self)
424	            } else {
425	                ParseState::ValueDone
426	            }
427	        } else if self.words >= self.capacity() {
428	            ParseState::ValueDone
429	        } else {
430	            ParseState::Opt(self)
431	        }
432	    }
433	}
434	
435	/// Whether an option's values form a delimited group that can hold more than
436	/// one fragment and whose fragments are validated while typed.
437	///
438	/// Single-value options (a maximum of one) are excluded: their delimiter only
439	/// joins several suggestions into one word, so completed fragments are not
440	/// validated against each other.
441	fn is_strict_group_arg(arg: &clap::Arg) -> bool {
442	    arg.get_value_delimiter().is_some()
443	        && arg.get_num_args().expect("built").max_values() > 1
444	        && possible_values(arg).is_some()
445	}
446	
447	/// The canonical possible-value name for `fragment`, honoring aliases and the
448	/// argument's case-insensitivity, or `None` when it is not a legal value.
449	fn canonical_possible_value(arg: &clap::Arg, fragment: &str) -> Option<String> {
450	    let ignore_case = arg.is_ignore_case_set();
451	    possible_values(arg)?
452	        .find(|value| value.matches(fragment, ignore_case))
453	        .map(|value| value.get_name().to_owned())
454	}
455	
456	/// Complete the word under the cursor for a strict delimited group.
457	///
458	/// Fragments already committed in earlier shell words are read from `state`;
459	/// fragments committed within the word under the cursor are validated here.
460	/// The fragment still being typed is matched against the possible values, and
461	/// every suggestion keeps the typed prefix (prior fragments and delimiters).
462	/// Any empty, unknown, duplicated, or over-capacity fragment yields an empty
463	/// result.
464	fn complete_strict_group(cursor: &str, state: &OptState<'_>) -> Vec<CompletionCandidate> {
465	    debug!(
466	        "complete_strict_group: arg={:?}, cursor={cursor:?}, used={:?}, invalid={}",
467	        state.opt.get_id(),
468	        state.used,
469	        state.invalid
470	    );
471	    if state.invalid {
472	        return Vec::new();
473	    }
474	    let delimiter = state.opt.get_value_delimiter().expect("strict group");
475	    let capacity = state.capacity();
476	
477	    let ends_with_delimiter = cursor.ends_with(delimiter);
478	    let mut parts = cursor.split(delimiter);
479	    let typed = if ends_with_delimiter {
480	        // The cursor sits right after a delimiter: the trailing empty element
481	        // is the fresh fragment being typed, not a committed value.
482	        parts.next_back();
483	        ""
484	    } else {
485	        parts.next_back().unwrap_or("")
486	    };
487	
488	    let mut used = state.used.clone();
489	    for fragment in parts {
490	        if used.len() >= capacity {
491	            return Vec::new();
492	        }
493	        match canonical_possible_value(state.opt, fragment) {
494	            Some(name) if !used.contains(&name) => used.push(name),
495	            _ => return Vec::new(),
496	        }
497	    }
498	
499	    if used.len() >= capacity {
500	        // Every slot is taken; there is no room for another fragment.
501	        return Vec::new();
502	    }
503	
504	    // Retain the text typed before the current fragment, including the last
505	    // delimiter, so suggestions replace only the fragment under the cursor.
506	    let prefix = cursor
507	        .rfind(delimiter)
508	        .map(|pos| cursor[..pos + delimiter.len_utf8()].to_owned());
509	
510	    let possible = possible_values(state.opt).expect("strict group");
511	    let mut values = complete_candidates_str(typed, possible_value_candidates(possible));
512	    // A value already committed to the group cannot be repeated.
513	    values.retain(|candidate| {
514	        candidate
515	            .get_value()
516	            .to_str()
517	            .is_none_or(|name| !used.iter().any(|used| used == name))
518	    });
519	
520	    if let Some(prefix) = prefix {
521	        values = values
522	            .into_iter()
523	            .map(|comp| comp.add_prefix(prefix.clone()))
524	            .collect();
525	    }
526	    values = values
527	        .into_iter()
528	        .map(|comp| {
529	            if comp.get_tag().is_some() {
530	                comp
531	            } else {
532	                comp.tag(Some(state.opt.to_string().into()))
533	            }
534	        })
535	        .collect();
536	
537	    values
538	}
539	
540	fn complete_arg(
541	    arg: &clap_lex::ParsedArg<'_>,
542	    cmd: &clap::Command,
543	    current_dir: Option<&std::path::Path>,
544	    pos_index: usize,
545	    is_escaped: bool,
546	    state: ParseState<'_>,
547	    used_args: &[clap::Id],
548	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
549	    debug!(
550	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
551	        arg,
552	        cmd.get_name(),
553	        current_dir,
554	        pos_index,
555	        state
556	    );
557	    let mut completions = Vec::<CompletionCandidate>::new();
558	
559	    match state {
560	        ParseState::ValueDone => {
561	            if !is_escaped {
562	                if let Ok(value) = arg.to_value() {
563	                    completions.extend(complete_subcommand(value, cmd));
564	                }
565	            }
566	
567	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
568	                completions.extend(complete_arg_value(
569	                    arg.to_value(),
570	                    positional,
571	                    current_dir,
572	                    0,
573	                ));
574	            }
575	            if !is_escaped {
576	                completions.extend(complete_option(arg, cmd, current_dir));
577	            }
578	        }
579	        ParseState::Pos((_, num_arg)) => {
580	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
581	                completions.extend(complete_arg_value(
582	                    arg.to_value(),
583	                    positional,
584	                    current_dir,
585	                    num_arg.saturating_sub(1),
586	                ));
587	                if !is_escaped
588	                    && positional
589	                        .get_num_args()
590	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
591	                {
592	                    completions.extend(complete_option(arg, cmd, current_dir));
593	                }
594	            }
595	        }
596	        ParseState::Opt(state) => {
597	            if state.is_strict_group() {
598	                // Every word belongs to the pending delimited group until it is
599	                // complete; it is never an option, positional, or subcommand.
600	                if let Ok(cursor) = arg.to_value() {
601	                    completions.extend(complete_strict_group(cursor, &state));
602	                }
603	            } else {
604	                let opt = state.opt;
605	                // `words` counts already-consumed values; the word under the
606	                // cursor is the next one, so the option sees one more value.
607	                let count = state.words + 1;
608	                completions.extend(complete_arg_value(
609	                    arg.to_value(),
610	                    opt,
611	                    current_dir,
612	                    count.saturating_sub(1),
613	                ));
614	                let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
615	                if count > min && can_switch_to_other_arg(opt, arg) {
616	                    // The option's required values are satisfied and this word
617	                    // would be parsed as a new flag rather than another value, so
618	                    // also complete it as a positional, flag, option or subcommand.
619	                    completions.extend(complete_arg(
620	                        arg,
621	                        cmd,
622	                        current_dir,
623	                        pos_index,
624	                        is_escaped,
625	                        ParseState::ValueDone,
626	                        used_args,
627	                    )?);
628	                }
629	            }
630	        }
631	    }
632	    filter_unavailable_args(&mut completions, cmd, used_args);
633	    if completions.iter().any(|a| !a.is_hide_set()) {
634	        completions.retain(|a| !a.is_hide_set());
635	    }
636	    dedup_argument_candidates(&mut completions, arg.is_empty());
637	
638	    let mut tags = Vec::new();
639	    for candidate in &completions {
640	        let tag = candidate.get_tag().cloned();
641	        if !tags.contains(&tag) {
642	            tags.push(tag);
643	        }
644	    }
645	    completions.sort_by_key(|c| {
646	        (
647	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
648	            c.get_display_order(),
649	        )
650	    });
651	
652	    Ok(completions)
653	}
