903	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
904	    debug!(
905	        "complete_subcommand: cmd={:?}, value={:?}",
906	        cmd.get_name(),
907	        value
908	    );
909	
910	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
911	        .into_iter()
912	        .filter(|x| x.get_value().starts_with(value))
913	        .collect();
914	    if cmd.is_allow_external_subcommands_set() {
915	        let external_completer = cmd.get::<SubcommandCandidates>();
916	        if let Some(completer) = external_completer {
917	            scs.extend(complete_value_candidates_str(
918	                value,
919	                completer.value_candidates(),
920	            ));
921	        }
922	    }
923	
924	    scs.dedup();
925	    scs
926	}
