933	    p.get_arguments()
934	        .filter_map(|a| {
935	            a.get_long_and_visible_aliases().map(|longs| {
936	                longs
937	                    .into_iter()
938	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
939	            })
940	        })
941	        .flatten()
942	        .collect()
943	}
