1034	fn populate_command_candidate(
1035	    candidate_name: &str,
1036	    cmd: &clap::Command,
1037	    subcommand: &clap::Command,
1038	) -> CompletionCandidate {
1039	    CompletionCandidate::new(candidate_name.to_owned())
1040	        .help(subcommand.get_about().cloned())
1041	        .id(Some(format!("command::{candidate_name}")))
1042	        .tag(Some(
1043	            cmd.get_subcommand_help_heading()
1044	                .unwrap_or("Commands")
1045	                .to_owned()
1046	                .into(),
1047	        ))
1048	        .display_order(Some(subcommand.get_display_order()))
1049	        .hide(subcommand.is_hide_set())
1050	}
