1095	/// Whether the argument can be addressed by the long flag `flag`,
1096	/// including visible and hidden aliases.
1097	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
1098	    arg.get_long() == Some(flag)
1099	        || arg
1100	            .get_all_aliases()
1101	            .is_some_and(|aliases| aliases.contains(&flag))
1102	}
1103	
1104	/// Whether the argument can be addressed by the short flag `flag`,
1105	/// including visible and hidden aliases.
1106	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
1107	    arg.get_short() == Some(flag)
1108	        || arg
1109	            .get_all_short_aliases()
1110	            .is_some_and(|aliases| aliases.contains(&flag))
1111	}
