6	/// Build the `tool` command used throughout these tests:
7	/// - automatic help and version flags are disabled
8	/// - the root declares a required, non-multiple `format` group whose members
9	///   are the value-free `--json`/`--yaml` flags (visible aliases `--js`/`--yml`)
10	/// - `--output` takes one of `file`/`stream`
11	/// - the `run` subcommand (visible alias `r`) declares its own required,
12	///   non-multiple group whose members are the value-free `--text`/`--binary`
13	///   flags (visible aliases `--txt`/`--bin`) and accepts the positional
14	///   values `job`/`log`
15	fn mutex_group_tool() -> Command {
16	    Command::new("tool")
17	        .disable_help_flag(true)
18	        .disable_version_flag(true)
19	        .disable_help_subcommand(true)
20	        .arg(
21	            clap::Arg::new("json")
22	                .long("json")
23	                .visible_alias("js")
24	                .action(clap::ArgAction::SetTrue),
25	        )
26	        .arg(
27	            clap::Arg::new("yaml")
28	                .long("yaml")
29	                .visible_alias("yml")
30	                .action(clap::ArgAction::SetTrue),
31	        )
32	        .group(
33	            ArgGroup::new("format")
34	                .args(["json", "yaml"])
35	                .required(true),
36	        )
37	        .arg(
38	            clap::Arg::new("output")
39	                .long("output")
40	                .value_parser(["file", "stream"]),
41	        )
42	        .subcommand(
43	            Command::new("run")
44	                .visible_alias("r")
45	                .disable_help_flag(true)
46	                .disable_version_flag(true)
47	                .disable_help_subcommand(true)
48	                .arg(
49	                    clap::Arg::new("text")
50	                        .long("text")
51	                        .visible_alias("txt")
52	                        .action(clap::ArgAction::SetTrue),
53	                )
54	                .arg(
55	                    clap::Arg::new("binary")
56	                        .long("binary")
57	                        .visible_alias("bin")
58	                        .action(clap::ArgAction::SetTrue),
59	                )
60	                .group(
61	                    ArgGroup::new("kind")
62	                        .args(["text", "binary"])
63	                        .required(true),
64	                )
65	                .arg(clap::Arg::new("item").value_parser(["job", "log"])),
66	        )
67	}
