69	fn complete_group(cmd: &mut Command, args: &[&str]) -> Vec<CompletionCandidate> {
70	    let args: Vec<std::ffi::OsString> = args.iter().map(std::ffi::OsString::from).collect();
71	    let arg_index = args.len() - 1;
72	    clap_complete::engine::complete(cmd, args, arg_index, None).unwrap()
73	}
74	
75	fn group_values(args: &[&str]) -> Vec<String> {
76	    let mut cmd = mutex_group_tool();
77	    complete_group(&mut cmd, args)
78	        .into_iter()
79	        .map(|candidate| candidate.get_value().to_string_lossy().into_owned())
80	        .collect()
81	}
