    // Ensure any child processes called for custom completers don't activate their own
    // completion logic.
    // SAFETY: should only be called during application initialization.  Yeah, this is a weak
    // argument but the choice is that or staying on the old edition.
    unsafe {
        std::env::remove_var(self.var);
    }

    let shell = self
        .shells
        .completer_for_path(std::path::Path::new(&name))?;

    let mut cmd = (self.factory)();
    cmd.build();

    let completer = args.remove(0);
    let escape_index = args
        .iter()
        .position(|a| *a == "--")
        .map(|i| i + 1)
        .unwrap_or(args.len());
    args.drain(0..escape_index);
    if args.is_empty() {
        let mut buf = Vec::new();
        self.write_registration(&cmd, current_dir, shell, completer, &mut buf)?;
        std::io::stdout().write_all(&buf)?;
    } else {
        let mut buf = Vec::new();
        shell.write_complete(&mut cmd, args, current_dir, &mut buf)?;
        std::io::stdout().write_all(&buf)?;
    }

    Ok(true)
}

